import {rank,normalizePreferences,compareOffers,explainConcentration} from './engine.js';
const FAMILY=['warm floral','warm spicy','gourmand','fruity floral','citrus','woody','fresh fruity'];
const NOTES=['lavender','orange blossom','vanilla','coffee','wild berries','jasmine','sandalwood','sicilian lemon','cedarwood','dark berries','musk','amber','green pear','ambroxan'];
export async function init(doc=document,fetcher=fetch,storage=localStorage){const $=id=>doc.getElementById(id);let catalog,results=[],shortlist=[];
 const readShort=()=>{try{return JSON.parse(storage.getItem('scentcompass.shortlist')||'[]').filter(x=>typeof x==='string')}catch{return[]}};shortlist=readShort();
 const chips=(id,values,name)=>$(id).innerHTML=values.map(v=>`<label><input type="checkbox" name="${name}" value="${v}"><span>${v}</span></label>`).join('');chips('families',FAMILY,'families');chips('liked',NOTES,'liked');$('disliked').innerHTML+=[...NOTES].sort().map(v=>`<option>${v}</option>`).join('');
 function getPrefs(){const fd=new doc.defaultView.FormData($('preferences'));return normalizePreferences({country:fd.get('country'),families:fd.getAll('families'),liked_notes:fd.getAll('liked'),disliked_notes:[$('disliked').value].filter(Boolean),occasions:[$('occasion').value],intensity:$('intensity').value,budget:Number($('budget').value)});}
 const money=(n,c)=>new Intl.NumberFormat(c==='CAD'?'en-CA':'en-US',{style:'currency',currency:c}).format(n);
 function save(){storage.setItem('scentcompass.shortlist',JSON.stringify(shortlist));$('shortlistCount').textContent=shortlist.length;}
 function render(){const p=getPrefs();results=rank(catalog,p);const sort=$('sort').value;if(sort==='value')results.sort((a,b)=>a.best_offer.price_per_ml-b.best_offer.price_per_ml||a.id.localeCompare(b.id));if(sort==='price')results.sort((a,b)=>a.best_offer.price-b.best_offer.price||a.id.localeCompare(b.id));$('resultTitle').textContent=`${results.length} match${results.length===1?'':'es'} in ${p.country==='CA'?'Canada':'the United States'}`;$('status').textContent=results.length?'Hard exclusions applied before scoring. Scores explain catalog similarity, not personal certainty.':'No products remain. Try another country, a higher budget, or remove an excluded note.';
  $('cards').innerHTML=results.map(r=>`<article class="card" data-id="${r.id}"><div class="cardtop"><div><span class="meta">${r.brand}</span><h3>${r.name}</h3><span class="meta">${r.concentration} · ${r.intensity}</span></div><span class="score" aria-label="${Math.round(r.score)} percent match">${Math.round(r.score)}</span></div><p>${r.description}</p><div class="notes">${r.notes.map(n=>`<span class="note">${n}</span>`).join('')}</div><p class="reason"><strong>Why it matched</strong><br>${r.reasons.join(' · ')}</p><div class="offer"><div class="offerline"><div><span class="meta">Best recorded value</span><br><strong>${money(r.best_offer.price,r.best_offer.currency)}</strong> / ${r.best_offer.size_ml} mL</div><div><span class="meta">Per mL</span><br><strong>${money(r.best_offer.price_per_ml,r.best_offer.currency)}</strong></div></div><p class="sourceTime">${r.best_offer.retailer} · captured Sep 14, 2026 · ${r.best_offer.status}</p><div class="actions"><a href="${r.best_offer.url}" target="_blank" rel="noopener noreferrer">Check retailer ↗</a><button data-save="${r.id}">${shortlist.includes(r.id)?'Saved ✓':'Shortlist'}</button></div><details class="details"><summary>Compare bottles & concentration</summary><p>${explainConcentration(r.concentration)}</p><table class="offerTable">${compareOffers(r.offers).map(o=>`<tr><td>${o.retailer}</td><td>${o.size_ml} mL</td><td>${money(o.price,o.currency)}</td><td>${money(o.price_per_ml,o.currency)}/mL</td></tr>`).join('')}</table><p><a href="${r.source}" target="_blank" rel="noopener noreferrer">Catalog description source ↗</a></p></details></div></article>`).join('');
  doc.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>toggle(b.dataset.save));
 }
 function toggle(id){shortlist=shortlist.includes(id)?shortlist.filter(x=>x!==id):[...shortlist,id];save();render();renderShort();return shortlist.includes(id);}
 function renderShort(){const products=catalog?.products.filter(p=>shortlist.includes(p.id))||[];$('shortlistCards').innerHTML=products.length?products.map(p=>`<article class="shortitem"><span class="meta">${p.brand}</span><h3>${p.name}</h3><p>${p.concentration} · ${p.notes.join(', ')}</p><button class="textButton" data-remove="${p.id}">Remove</button></article>`).join(''):'<p>Your shortlist is empty.</p>';$('shortlistCards').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>toggle(b.dataset.remove));}
 function openShort(open){$('shortlist').hidden=!open;$('scrim').hidden=!open;if(open)renderShort();}
 try{const res=await fetcher('catalog.json');if(!res.ok)throw Error('catalog unavailable');catalog=await res.json();$('status').textContent='';save();render();}catch(e){$('status').textContent='Unable to load the catalog. Serve the dist folder over HTTP and reload.';return null;}
 $('preferences').onsubmit=e=>{e.preventDefault();render()};$('preferences').onreset=()=>setTimeout(()=>{ $('currencyLabel').textContent='USD';render()},0);$('sort').onchange=render;doc.querySelectorAll('[name=country]').forEach(x=>x.onchange=()=>{$('currencyLabel').textContent=x.value==='CA'?'CAD':'USD';$('budget').value=x.value==='CA'?250:200;render()});$('shortlistButton').onclick=()=>openShort(true);$('closeShortlist').onclick=()=>openShort(false);$('scrim').onclick=()=>openShort(false);$('clearShortlist').onclick=()=>{shortlist=[];save();render();renderShort()};
 const ctx=doc.modelContext;if(ctx?.registerTool){try{await ctx.registerTool({name:'set_scent_profile',title:'Set scent profile',description:'Apply fragrance preferences and update visible ranked matches.',inputSchema:{type:'object',properties:{country:{enum:['US','CA']},families:{type:'array',items:{type:'string'}},liked_notes:{type:'array',items:{type:'string'}},disliked_notes:{type:'array',items:{type:'string'}},occasions:{type:'array',items:{type:'string'}},intensity:{enum:['soft','medium','bold']},budget:{type:'number',minimum:0,maximum:1000}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const p=normalizePreferences(input);doc.querySelector(`[name=country][value=${p.country}]`).checked=true;doc.querySelectorAll('[name=families],[name=liked]').forEach(x=>x.checked=(x.name==='families'?p.families:p.liked_notes).includes(x.value));$('disliked').value=p.disliked_notes[0]||'';$('occasion').value=p.occasions[0]||'daily';$('intensity').value=p.intensity;$('budget').value=Number.isFinite(p.budget)?p.budget:(p.country==='CA'?250:200);$('currencyLabel').textContent=p.currency;render();return {country:p.country,matches:results.length,top_ids:results.slice(0,3).map(x=>x.id)}}});}catch{}}
 return {catalog,getPrefs,render,toggle,get results(){return results},get shortlist(){return shortlist}};
}
if(typeof document!=='undefined')init();
